  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除：0-未删除，1-已删除',
  `category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '帖子分类',
  `pinned` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否置顶',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_forum_posts_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_forum_posts_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_user_deleted`(`user_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_status_created_at`(`status` ASC, `created_at` DESC) USING BTREE,
  INDEX `idx_category_status_created`(`category` ASC, `status` ASC, `created_at` DESC) USING BTREE,
  INDEX `idx_pinned_status_created`(`pinned` DESC, `status` ASC, `created_at` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '论坛帖子表' ROW_FORMAT = Dynamic;

