  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ip_blacklists_ip`(`ip` ASC) USING BTREE,
  INDEX `idx_ip_blacklists_status`(`status` ASC) USING BTREE,
  INDEX `idx_ip_blacklists_expire_at`(`expire_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'IP 黑名单表' ROW_FORMAT = Dynamic;

