  INDEX `idx_username_time`(`username` ASC, `login_time` DESC) USING BTREE,
  INDEX `idx_status_time`(`status` ASC, `login_time` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 173 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '登录日志表' ROW_FORMAT = Dynamic;

