-- ----------------------------
-- Table structure for marketplace_applications
-- ----------------------------
DROP TABLE IF EXISTS `marketplace_applications`;
CREATE TABLE `marketplace_applications`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请 ID',
  `listing_id` bigint NOT NULL COMMENT '挂牌 ID',
  `owner_id` bigint NOT NULL COMMENT '车主用户 ID',
  `renter_id` bigint NOT NULL COMMENT '租客用户 ID',
  `delivery_mode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OWNER_MEETUP' COMMENT '交付方式',
  `requested_start_time` datetime NOT NULL COMMENT '申请开始时间',
  `requested_end_time` datetime NOT NULL COMMENT '申请结束时间',
  `meetup_time` datetime NULL DEFAULT NULL COMMENT '约定交付时间',
  `meetup_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '约定交付地点',
  `renter_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租客留言',
  `owner_reply` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车主回复',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_OWNER_CONFIRMATION' COMMENT '申请状态',
  `confirmed_at` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `handover_at` datetime NULL DEFAULT NULL COMMENT '交付完成时间',
  `return_requested_at` datetime NULL DEFAULT NULL COMMENT '归还申请时间',
  `completed_at` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `cancelled_at` datetime NULL DEFAULT NULL COMMENT '取消时间',
  `rejected_at` datetime NULL DEFAULT NULL COMMENT '拒绝时间',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_marketplace_applications_listing`(`listing_id` ASC) USING BTREE,
  INDEX `idx_marketplace_applications_owner`(`owner_id` ASC) USING BTREE,
  INDEX `idx_marketplace_applications_renter`(`renter_id` ASC) USING BTREE,
  INDEX `idx_marketplace_applications_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '个人出租申请表' ROW_FORMAT = Dynamic;

