-- ----------------------------
-- Table structure for marketplace_listings
-- ----------------------------
DROP TABLE IF EXISTS `marketplace_listings`;
CREATE TABLE `marketplace_listings`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '挂牌 ID',
  `owner_id` bigint NOT NULL COMMENT '车主用户 ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '车辆名称',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '车辆类型',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交付地点',
  `latitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度',
  `longitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `price_per_hour` decimal(10, 2) NOT NULL COMMENT '每小时租金',
  `deposit` decimal(10, 2) NULL DEFAULT NULL COMMENT '押金',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '图片 URL',
  `delivery_mode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OWNER_MEETUP' COMMENT '交付方式',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVAILABLE' COMMENT '挂牌状态',
  `review_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '审核状态',
  `review_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核备注',
  `reviewer_id` bigint NULL DEFAULT NULL COMMENT '审核人 ID',
  `reviewed_at` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `available_from` datetime NOT NULL COMMENT '可租开始时间',
  `available_to` datetime NOT NULL COMMENT '可租结束时间',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_marketplace_listings_owner`(`owner_id` ASC) USING BTREE,
  INDEX `idx_marketplace_listings_status`(`status` ASC) USING BTREE,
  INDEX `idx_marketplace_listings_type`(`type` ASC) USING BTREE,
  INDEX `idx_marketplace_listings_review_status`(`review_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '个人出租挂牌表' ROW_FORMAT = Dynamic;

