  `quantity` int NOT NULL DEFAULT 1 COMMENT '租赁数量',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_bicycle_id`(`bicycle_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_user_deleted`(`user_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_user_status_deleted`(`user_id` ASC, `status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_status_deleted`(`status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_start_time`(`start_time` DESC) USING BTREE,
  INDEX `idx_user_start_time`(`user_id` ASC, `start_time` DESC) USING BTREE,
  INDEX `idx_deleted_start_time`(`deleted` ASC, `start_time` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租赁记录表' ROW_FORMAT = Dynamic;

