  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_visit_logs_username`(`username` ASC) USING BTREE,
  INDEX `idx_visit_logs_method`(`request_method` ASC) USING BTREE,
  INDEX `idx_visit_logs_ip`(`visit_ip` ASC) USING BTREE,
  INDEX `idx_visit_logs_status`(`status` ASC) USING BTREE,
  INDEX `idx_visit_logs_time`(`visited_at` ASC) USING BTREE,
  INDEX `idx_visited_at`(`visited_at` DESC) USING BTREE,
  INDEX `idx_ip_time`(`visit_ip` ASC, `visited_at` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7018 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '访客日志表' ROW_FORMAT = Dynamic;

